class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is NodeType) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    } else if (value is DaVinciLogLevel) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    } else if (value is ValidationErrorKind) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    } else if (value is PollingStatusKind) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    } else if (value is OpenIdConfigMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    } else if (value is DaVinciConfigMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    } else if (value is OptionMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    } else if (value is DeviceMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    } else if (value is PasswordPolicyMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is RichContentReplacementMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is RichContentMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is CollectorMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is CollectorValueMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is ValidationErrorMessage) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else if (value is NodeMessage) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    } else if (value is SessionMessage) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else if (value is TokenMessage) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else if (value is PollingEventMessage) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : NodeType.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : DaVinciLogLevel.values[value];
      case 131:
        final value = readValue(buffer) as int?;
        return value == null ? null : ValidationErrorKind.values[value];
      case 132:
        final value = readValue(buffer) as int?;
        return value == null ? null : PollingStatusKind.values[value];
      case 133:
        return OpenIdConfigMessage.decode(readValue(buffer)!);
      case 134:
        return DaVinciConfigMessage.decode(readValue(buffer)!);
      case 135:
        return OptionMessage.decode(readValue(buffer)!);
      case 136:
        return DeviceMessage.decode(readValue(buffer)!);
      case 137:
        return PasswordPolicyMessage.decode(readValue(buffer)!);
      case 138:
        return RichContentReplacementMessage.decode(readValue(buffer)!);
      case 139:
        return RichContentMessage.decode(readValue(buffer)!);
      case 140:
        return CollectorMessage.decode(readValue(buffer)!);
      case 141:
        return CollectorValueMessage.decode(readValue(buffer)!);
      case 142:
        return ValidationErrorMessage.decode(readValue(buffer)!);
      case 143:
        return NodeMessage.decode(readValue(buffer)!);
      case 144:
        return SessionMessage.decode(readValue(buffer)!);
      case 145:
        return TokenMessage.decode(readValue(buffer)!);
      case 146:
        return PollingEventMessage.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

