/// Native-to-Dart streams. One channel carries every poll's statuses, tagged with their
/// [PollingEventMessage.pollId]: Pigeon's event-channel methods take no parameters, and a
/// channel per poll would need registering and tearing down natively for each one.
/// Every running poll's statuses.
///
/// Returns a broadcast [Stream] of events from the `pollingEvents` event channel.
///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<PollingEventMessage> pollingEvents({String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel pollingEventsChannel = EventChannel(
    'dev.flutter.pigeon.ping_davinci.PingDaVinciEventApi.pollingEvents$instanceName',
    pigeonMethodCodec,
  );
  return pollingEventsChannel.receiveBroadcastStream().map((dynamic event) {
    return event as PollingEventMessage;
  });
}
